@app.get('/api/files/signed/{file_uuid}')
async def get_minio_presigned_file(
    file_uuid: str,
    conn: asyncpg.Connection = Depends(get_pg_connection),
    current_user: TokenData = Depends(verify_jwt)
):
    row = await conn.fetchrow(
        "SELECT bucket_name, object_key FROM user_files WHERE file_uuid = $1 AND user_id = $2",
        file_uuid,
        current_user.user_id
    )
    if not row:
        raise HTTPException(status_code=404, detail="File record not found")

    url = minio_client.get_presigned_url(
        "GET",
        bucket_name=row["bucket_name"],
        object_name=row["object_key"],
        expires=timedelta(hours=1)
    )
    return {"download_url": url}
